acc_car:
#ifdef GL_FRAGMENT_PRECISION_HIGH
precision highp float;
#else
precision mediump float;
#endif
varying vec2 v_uv;
uniform vec2 u_size;
uniform vec3 u_body;
uniform vec2 u_dim;
float box(vec2 q, vec2 c, vec2 b, float r) {
vec2 e = abs(q - c) - b + vec2(r);
return length(max(e, 0.0)) + min(max(e.x, e.y), 0.0) - r;
}
void main() {
float a = u_size.x / u_size.y;
vec2 q = vec2((v_uv.x - 0.5) * a, v_uv.y);
float aa = 1.2 / u_size.y;
float ax = abs(q.x);
vec2 s = (q - vec2(0.0, 0.94)) / vec2(0.82, 0.075);
float shadow = (1.0 - smoothstep(0.4, 1.0, dot(s, s))) * 0.55;
vec4 c = vec4(0.0, 0.0, 0.0, shadow);
float ty = box(vec2(ax, q.y), vec2(0.53, 0.86), vec2(0.105, 0.095), 0.03);
float kt = 1.0 - smoothstep(-aa, aa, ty);
c = mix(c, vec4(vec3(0.07), 1.0), kt);
float f = clamp((q.y - 0.17) / 0.30, 0.0, 1.0);
float cab = box(vec2(ax * 0.62 / mix(0.43, 0.62, f), q.y), vec2(0.0, 0.32), vec2(0.62, 0.15), 0.07);
float body = box(q, vec2(0.0, 0.63), vec2(0.70, 0.20), 0.11);
float mir = box(vec2(ax, q.y), vec2(0.70, 0.40), vec2(0.07, 0.035), 0.03);
float sil = min(min(cab, body), mir);
float k = 1.0 - smoothstep(-aa, aa, sil);
float lit = 0.62 + 0.38 * (1.0 - q.y);
lit *= 1.0 - 0.38 * smoothstep(0.40, 0.72, ax);
lit += 0.30 * (1.0 - smoothstep(0.0, 0.025, abs(q.y - 0.455))) * (1.0 - smoothstep(0.50, 0.66, ax));
lit *= 0.70 + 0.30 * smoothstep(-0.06, -0.005, -sil);
vec3 col = u_body * lit;
float win = box(vec2(ax * 0.55 / mix(0.37, 0.55, f), q.y), vec2(0.0, 0.335), vec2(0.55, 0.105), 0.045);
float kw = 1.0 - smoothstep(-aa, aa, win);
vec3 glass = vec3(0.05, 0.06, 0.08) + vec3(0.16, 0.18, 0.21) * (1.0 - smoothstep(0.0, 0.08, abs(q.x * 0.6 + q.y - 0.42))) + 0.08 * (1.0 - f);
col = mix(col, glass, kw);
float lamp = box(q, vec2(0.0, 0.53), vec2(0.66, 0.035), 0.02);
float kl = 1.0 - smoothstep(-aa, aa, lamp);
col = mix(col, vec3(0.10, 0.10, 0.11) + 0.18 * u_body * (1.0 - smoothstep(0.0, 0.66, ax)), kl);
float plate = box(q, vec2(0.0, 0.69), vec2(0.15, 0.045), 0.01);
col = mix(col, u_body * 0.35, 1.0 - smoothstep(-aa, aa, plate));
float diff = box(q, vec2(0.0, 0.80), vec2(0.52, 0.025), 0.02);
col = mix(col, vec3(0.06), 1.0 - smoothstep(-aa, aa, diff));
c = mix(c, vec4(col, 1.0), k);
gl_FragColor = vec4(c.rgb * (1.0 - 0.65 * u_dim.x), c.a);
}

acc_lane:
#ifdef GL_FRAGMENT_PRECISION_HIGH
precision highp float;
#else
precision mediump float;
#endif
varying vec2 v_uv;
uniform vec2 u_size;
uniform vec4 u_geo;
uniform vec3 u_line;
uniform vec3 u_ground;
uniform vec4 u_gap;
uniform vec3 u_gapc;
uniform vec4 u_nb[4];
float tOf(float z, float kf) { return 1.0 / (1.0 + z * kf); }
void main() {
vec2 p = v_uv * u_size;
float hy = u_geo.x * u_size.y;
float t = (p.y - hy) / (u_size.y - hy);
vec4 c = vec4(0.0);
if (t > 0.0) {
float kf = 1.0 / u_geo.z - 1.0;
float z = (1.0 / t - 1.0) / kf;
float hw = u_geo.y * t;
float X = (p.x - 0.5 * u_size.x) / hw;
float fade = 1.0 - smoothstep(0.55, 1.0, z);
float edge = smoothstep(0.0, 48.0, min(p.x, u_size.x - p.x)) * smoothstep(0.0, 16.0, u_size.y - p.y);
float ground = (0.30 + 0.70 * clamp(1.0 - z, 0.0, 1.0)) * (1.0 - smoothstep(1.4, 3.4, abs(X))) * edge;
c = vec4(u_ground, ground * fade);
if (u_gap.x > 0.0 && z < u_gap.x) {
float k = u_gap.z * (1.0 - smoothstep(0.72, 0.92, abs(X))) * smoothstep(0.0, 0.04, u_gap.x - z);
c.rgb = mix(c.rgb, u_gapc, k);
c.a = max(c.a, k * fade);
if (u_gap.y > 0.5) {
for (int i = 0; i < 2; i++) {
float tc = tOf(u_gap.x * (0.45 + 0.22 * float(i)), kf);
float yc = hy + (u_size.y - hy) * tc;
float d = (p.y - yc - abs(X) * u_geo.y * tc * 0.28) / (u_geo.w * tc * 0.9 + 0.8);
float on = (1.0 - smoothstep(0.6, 1.0, abs(d))) * (1.0 - smoothstep(0.42, 0.52, abs(X)));
if (float(i) < u_gap.y) { c.rgb = mix(c.rgb, u_gapc, on); c.a = max(c.a, on * fade); }
}
}
}
float lw = max(1.2, u_geo.w * t);
float dx = (abs(X) - 1.0) * hw;
float line = (1.0 - smoothstep(lw * 0.5 - 0.7, lw * 0.5 + 0.7, abs(dx))) * fade;
float glow = (1.0 - smoothstep(0.0, lw * 2.5 + 2.0, abs(dx))) * 0.25 * fade;
c.rgb = mix(c.rgb, u_line, max(line, glow));
c.a = max(c.a, max(line, glow));
for (int i = 0; i < 4; i++) {
vec4 n = u_nb[i];
if (abs(n.x) > 0.5) {
float tn = tOf(n.y, kf);
float wy = hy + (u_size.y - hy) * tn;
float bw = u_geo.y * tn * 0.62;
float bh = bw * 0.62;
vec2 q = vec2(p.x - (0.5 * u_size.x + n.x * 2.0 * u_geo.y * tn), p.y - (wy - bh));
if (abs(q.x) < bw + 4.0 && abs(q.y) < bh + 4.0) {
vec2 e = abs(q - vec2(0.0, bh * 0.35)) - vec2(bw, bh * 0.62) + vec2(bh * 0.2);
float sd = length(max(e, 0.0) / bh) * bh + min(max(e.x, e.y), 0.0) - bh * 0.2;
e = abs(q + vec2(0.0, bh * 0.45)) - vec2(bw * 0.68, bh * 0.45) + vec2(bh * 0.2);
sd = min(sd, length(max(e, 0.0) / bh) * bh + min(max(e.x, e.y), 0.0) - bh * 0.2);
float o = (1.0 - smoothstep(0.6, 1.6, abs(sd))) * n.z;
c.rgb = mix(c.rgb, u_line * 0.5 + vec3(0.5), o);
c.a = max(c.a, o);
}
}
}
}
gl_FragColor = vec4(c.rgb * (1.0 - 0.65 * u_gap.w), c.a);
}
